import{_ as l,l as i,o as e,c as d,v as o,p as n,x as t,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"循环不变量外提","description":"","frontmatter":{"title":"循环不变量外提","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/licm.md","filePath":"cs/licm.md","lastUpdated":1789023840000}'),h={name:"cs/licm.md"};function A(E,a,_,m,f,u){const r=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="循环不变量外提" tabindex="-1">循环不变量外提 <a class="header-anchor" href="#循环不变量外提" aria-label="Permalink to &quot;循环不变量外提&quot;">​</a></h1><div class="epigraph"><p>若计算在循环每一圈结果相同，且外提安全，就搬到前置头执行一次。安全包括异常、别名与执行频率。</p><footer>—— 据 Allen and Cocke, A Catalogue of Optimizing Transformations；龙书 9.5；Muchnick 整理</footer></div><p>上一课<a href="/cs/dce-adce">DCE</a>删死的。缺口是<strong>活但不随迭代变</strong>的表达式：<code>t = n*4</code> 在 <code>for</code> 里。LICM：识别循环、找不变、外提到 preheader。主干点过循环；自然循环识别后课正式收。本课假定可识别自然循环与前置头。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不变：操作数在循环外定义，或本身不变。外提：preheader 支配所有入口。缺口是<strong>安全性</strong>：load 在循环里可能不执行（保护在 <code>if</code> 后），外提会引入新的陷阱或多执行。必须：计算在原循环每次入口都必执行，或语言允许投机（无副作用）。</p><p>与 CSE：先 LICM 再 GVN，或不变表达式当循环外公共值。</p><h3 id="外提不是循环展开" tabindex="-1">外提不是循环展开 <a class="header-anchor" href="#外提不是循环展开" aria-label="Permalink to &quot;外提不是循环展开&quot;">​</a></h3><p>展开复制体；LICM 减少每圈工作。二者后课可组合。</p><p><span class="marginnote">Allen–Cocke。龙书循环优化。Appel 有短节。本课不写完整别名；load 外提默认要「必执行且无别名写」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对循环嵌套从内到外。SSA：名的 def 在循环外则不变。有循环内 def 则否。条件外提：用控制依赖或「循环内必经」分析。</p>',11)),(e(),n(p,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E8%87%AA%E7%84%B6%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20INV%5B%22%E4%B8%8D%E5%8F%98%E8%AE%A1%E7%AE%97%22%5D%0A%20%20INV%20--%3E%20SAFE%5B%22%E5%BF%85%E6%89%A7%E8%A1%8C%20%2F%20%E6%97%A0%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%0A%20%20SAFE%20--%3E%20PH%5B%22%E5%89%8D%E7%BD%AE%E5%A4%B4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>寄存器压力：外提过多拉长存活，可能更差——启发后课与寄存器分配交互。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><code>volatile</code> 与原子不外提。调用：须证明纯。整数溢出：C 对有符号溢出是 UB，外提可能改变「是否溢出」的路径——UB 课再钉。</p><p>不要外提可能别名的 load 跨过 store。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写强度削弱。后课默认：安全的不变计算进 preheader。下一课归纳变量与强度削弱：<code>i*4</code> 变成加法。</p><p>也不把 LICM 当多面体调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LICM：不变且安全的计算搬到前置头。</li><li>安全 = 无新副作用/陷阱，通常要必执行。</li><li>与 SSA 支配、循环识别绑定。</li><li>出处：Allen and Cocke；Aho et al. 龙书；Muchnick。</li></ul>',9))])}const k=l(h,[["render",A]]);export{S as __pageData,k as default};
